#include<iostream>
using namespace std;
#define MAXSIZE 100
#define OK 1
#define ERROR 0
#define OVERFLOW -2
typedef struct
{
	int *base;
	int front;
  	int rear;
}SqQueue;
int InitQueue(SqQueue &Q)
{//构造一个空队列Q
	Q.base=new int[MAXSIZE];          //为队列分配一个最大容量为MAXSIZE的数组空间
	if(!Q.base) return OVERFLOW;            //存储分配失败
	Q.front=Q.rear=0;                  //头尾指针置零，队列为空
	return OK;
}
int EnQueue(SqQueue& Q,int e)
{//在Q的队头插入新元素e
	if((Q.rear+1)%MAXSIZE==Q.front) return ERROR;
	Q.front=(Q.front-1+MAXSIZE)%MAXSIZE;
	Q.base[Q.front]=e;
	return OK;
}
int DeQueue(SqQueue &Q)
{//删除Q的队尾元素，返回其值
	Q.rear=(Q.rear-1+MAXSIZE)%MAXSIZE;
	return Q.base[Q.rear];
}
int main()
{
	int n;
	while(cin>>n&&n!=0)
	{
		SqQueue Q;
		InitQueue(Q);
		for(int i=0;i<n;i++)
		{
			int x;cin>>x;
			EnQueue(Q,x);
		}
		for(int i=0;i<n-1;i++)
			cout<<DeQueue(Q)<<" ";
		cout<<DeQueue(Q)<<endl;
	}
	return 0;
}

import pandas as pd
import re


def read_temperature_data(path='temperature.txt'):
    encodings = ('utf-8-sig', 'gbk', 'gb18030', 'utf-8')
    lines = None
    for enc in encodings:
        try:
            with open(path, 'r', encoding=enc) as f:
                lines = f.readlines()
            break
        except UnicodeDecodeError:
            continue
    if lines is None:
        with open(path, 'r', encoding='latin1') as f:
            lines = f.readlines()

    records = []
    row_indexes = []

    for raw in lines:
        line = raw.strip().replace('\ufeff', '')
        if not line:
            continue
        if '最高温度' in line and '最低温度' in line:
            continue

        if ',' in line:
            parts = [p.strip() for p in line.split(',')]
        elif ';' in line:
            parts = [p.strip() for p in line.split(';')]
        elif '\t' in line:
            parts = [p.strip() for p in line.split('\t')]
        else:
            parts = re.split(r'\s+', line)

        parts = [p for p in parts if p != '']
        if not parts:
            continue

        idx = None
        if len(parts) >= 4 and re.match(r'^[-+]?\d+$', parts[0]):
            idx = int(parts[0])
            parts = parts[1:]

        if len(parts) < 3:
            continue

        city = parts[0]
        high = parts[1].replace('℃', '').replace('°C', '').strip()
        low = parts[2].replace('℃', '').replace('°C', '').strip()

        high = re.sub(r'[^0-9\-\.]', '', high)
        low = re.sub(r'[^0-9\-\.]', '', low)

        if high == '' or low == '':
            continue

        records.append((city, int(float(high)), int(float(low))))
        if idx is not None:
            row_indexes.append(idx)

    if row_indexes and len(row_indexes) == len(records):
        df = pd.DataFrame(records, columns=['城市', '最高温度', '最低温度'], index=row_indexes)
    else:
        df = pd.DataFrame(records, columns=['城市', '最高温度', '最低温度'])

    return df


